def unitSuppressionColorBudget (A : Finset ℂ) (k : ℕ) : ℕ :=
  ((Finset.univ : Finset (Fin (Fintype.card (↥A × ↥A)))).product
    (Finset.range (witnessMassBudget k + 2))).sup (fun p => Nat.pair p.1.val p.2)

